## `cache.ts`

```ts
import Redis from "ioredis";

const redis = new Redis(process.env.REDIS_URL ?? "redis://localhost:6379");

const DEFAULT_TTL = 300;      // 5 min
const NEGATIVE_TTL = 30;      // cache "not found" briefly
const NOT_FOUND = "__NF__";

// in-process single-flight: concurrent misses for same key share one fetch
const inflight = new Map<string, Promise<unknown>>();

function jitter(ttl: number): number {
  // ±10% so keys don't expire in lockstep
  return Math.round(ttl * (0.9 + Math.random() * 0.2));
}

export async function getOrLoad<T>(
  key: string,
  loader: () => Promise<T | null>,
  ttl = DEFAULT_TTL,
): Promise<T | null> {
  try {
    const hit = await redis.get(key);
    if (hit !== null) return hit === NOT_FOUND ? null : (JSON.parse(hit) as T);
  } catch (err) {
    // Redis down → fall through to source, don't fail request
    console.warn("cache read failed", key, err);
  }

  const existing = inflight.get(key);
  if (existing) return existing as Promise<T | null>;

  const p = (async () => {
    try {
      const value = await loader();
      try {
        if (value === null) {
          await redis.set(key, NOT_FOUND, "EX", NEGATIVE_TTL);
        } else {
          await redis.set(key, JSON.stringify(value), "EX", jitter(ttl));
        }
      } catch (err) {
        console.warn("cache write failed", key, err);
      }
      return value;
    } finally {
      inflight.delete(key);
    }
  })();

  inflight.set(key, p);
  return p;
}

export async function invalidate(...keys: string[]): Promise<void> {
  if (keys.length === 0) return;
  try {
    await redis.del(...keys);
  } catch (err) {
    console.warn("cache invalidate failed", keys, err);
  }
}
```

## `profileCache.ts`

```ts
import { getOrLoad, invalidate } from "./cache";
import { db } from "./db";

export interface UserProfile {
  id: string;
  displayName: string;
  avatarUrl: string | null;
  bio: string | null;
  updatedAt: string;
}

// version prefix → bump on schema change to orphan old entries
const key = (userId: string) => `v1:user:profile:${userId}`;

export function getProfile(userId: string): Promise<UserProfile | null> {
  return getOrLoad(key(userId), () => db.profiles.findById(userId));
}

export async function updateProfile(
  userId: string,
  patch: Partial<Omit<UserProfile, "id" | "updatedAt">>,
): Promise<UserProfile> {
  const updated = await db.profiles.update(userId, patch); // write DB first
  await invalidate(key(userId));                           // then drop cache
  return updated;
}

export async function deleteProfile(userId: string): Promise<void> {
  await db.profiles.delete(userId);
  await invalidate(key(userId));
}
```

## `routes.ts`

```ts
import { Router } from "express";
import { getProfile, updateProfile } from "./profileCache";
import { requireAuth } from "./auth";

export const router = Router();

router.get("/users/:id/profile", async (req, res, next) => {
  try {
    const profile = await getProfile(req.params.id);
    if (!profile) return res.status(404).json({ error: "not found" });

    res.set("Cache-Control", "private, max-age=60");
    res.set("ETag", `"${profile.id}-${profile.updatedAt}"`);
    if (req.fresh) return res.status(304).end();

    res.json(profile);
  } catch (err) {
    next(err);
  }
});

router.patch("/users/:id/profile", requireAuth, async (req, res, next) => {
  try {
    if (req.user.id !== req.params.id) return res.status(403).end();
    const updated = await updateProfile(req.params.id, req.body);
    res.json(updated);
  } catch (err) {
    next(err);
  }
});
```

## Design notes

- **Invalidate, not update, on write.** Delete key after DB commit → next read repopulates. Avoids race where two writers set cache out of order.
- **Remaining race:** reader loads stale row, writer commits + deletes, reader then sets stale value. Window tiny; TTL bounds it. Need tighter → delayed double-delete (`invalidate` again ~500ms later) or version check on `updatedAt`.
- **Redis failure = degrade, not error.** All cache ops wrapped; DB stays source of truth.
- **Single-flight is per-process.** Many instances → still N loads on hot-key miss, not thousands. Need cluster-wide → Redis `SET NX` lock.
- **Privacy:** cache only public profile fields. Private data (email, settings) → separate key, or skip cache. `Cache-Control: private` keeps CDNs from storing it.
- **Multi-instance with local L1 cache** (not shown) → need pub/sub invalidation broadcast. Redis-only setup avoids that.

